      rxjs.operators.switchMap(function (_data) {
        if (_data) {
          return rxjs.of(_data);
        } else {
          if (!ADP.Utils.isUserLoggedIn()) {
            console.debug("User Preferences: User not logged in, skipping API call");
            return rxjs.of({});
          }
          return rxjs.ajax.get(getURL + user + ".json");
        }
      })
    );
  };

