        .ajax({
          url: URL + user,
          method: "POST",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body: queryStringParams,
        })
        .pipe(
          rxjs.operators.switchMap(function (_) {
            return rxjs.from(db.userPreferences.update(user, localUpdateData));
